const sfx_t g_sfx[SFX_COUNT] = {
    {"battle_hit", sfx_battle_hit, 4938},
    {"bomb", sfx_bomb, 15963},
    {"click", sfx_click, 551},
    {"door", sfx_door, 4276},
    {"footstep", sfx_footstep, 2291},
    {"hidden", sfx_hidden, 9612},
    {"hurt", sfx_hurt, 6174},
    {"lose", sfx_lose, 17812},
    {"pickup", sfx_pickup, 5751},
    {"powerup", sfx_powerup, 10690},
    {"story", sfx_story, 2205},
    {"win", sfx_win, 20106},
};

int sfx_find(const char *name)
{
    for (int i = 0; i < SFX_COUNT; i++) {
        if (strcmp(g_sfx[i].name, name) == 0) return i;
    }
    return -1;
}
